CREATE OR REPLACE FUNCTION public.push_sync_mutation_v2(target_user_id uuid, target_mutation_id uuid, target_device_id text, target_entity_type text, target_entity_id text, target_base_server_version bigint, target_version integer, target_payload jsonb, target_updated_at timestamp with time zone, target_deleted_at timestamp with time zone, target_resolves_conflict_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  existing_record public.sync_records%rowtype;
  existing_mutation public.sync_mutations%rowtype;
  next_server_version bigint;
  request_fingerprint text;
  response_payload jsonb;
  conflict_id uuid;
  record_existed boolean;
  legacy_guard_version bigint;
  legacy_guard_payload jsonb;
  resolution_conflict public.sync_conflicts%rowtype;
  focus_merge_required boolean := false;
begin
  if target_entity_type not in (
    'tasks','goals','habits','stats','progress','hashtags','accountability',
    'truenorth','amalgam','tracking','circadian','settings','daily_plans','task_events'
  ) or length(target_entity_id) not between 1 and 240 then
    raise exception using errcode = '22023', message = 'Unsupported synchronization entity';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(target_user_id::text || ':' || target_mutation_id::text, 0));
  request_fingerprint := encode(digest(convert_to(jsonb_build_object(
    'deviceId', target_device_id,
    'entityType', target_entity_type,
    'entityId', target_entity_id,
    'baseServerVersion', target_base_server_version,
    'version', target_version,
    'payload', target_payload,
    'updatedAt', target_updated_at,
    'deletedAt', target_deleted_at,
    'resolvesConflictId', target_resolves_conflict_id
  )::text, 'utf8'), 'sha256'), 'hex');

  select * into existing_mutation from public.sync_mutations
  where user_id = target_user_id and mutation_id = target_mutation_id;
  if found then
    -- Rows created by the pre-fingerprint protocol cannot prove which payload
    -- they acknowledged. Never consume a current client mutation based on that
    -- ambiguity: materialize both sides and require an explicit resolution.
    if existing_mutation.request_hash is null then
      select * into existing_record from public.sync_records
      where user_id = target_user_id and entity_type = target_entity_type and entity_id = target_entity_id;
      record_existed := found;
      insert into public.sync_conflicts (
        user_id, entity_type, entity_id, mutation_id, base_server_version,
        server_version, local_payload, server_payload, local_deleted_at, server_deleted_at,
        local_version, local_updated_at, server_missing
      ) values (
        target_user_id, target_entity_type, target_entity_id, target_mutation_id,
        target_base_server_version, coalesce(existing_record.server_version, existing_mutation.server_version, 0),
        target_payload, case when record_existed then existing_record.payload else '{}'::jsonb end,
        target_deleted_at, case when record_existed then existing_record.deleted_at else null end,
        target_version, target_updated_at, not record_existed
      ) on conflict (user_id, mutation_id) do nothing
      returning id into conflict_id;
      if conflict_id is null then
        select id into conflict_id from public.sync_conflicts
        where user_id = target_user_id and mutation_id = target_mutation_id;
      end if;
      response_payload := jsonb_build_object(
        'accepted', false,
        'replayMismatch', true,
        'conflictId', conflict_id,
        'serverMissing', not record_existed,
        'serverVersion', coalesce(existing_record.server_version, existing_mutation.server_version, 0),
        'record', case when record_existed then to_jsonb(existing_record) else null end
      );
      update public.sync_mutations set
        entity_type = target_entity_type,
        entity_id = target_entity_id,
        request_hash = request_fingerprint,
        result = response_payload
      where user_id = target_user_id and mutation_id = target_mutation_id;
      return response_payload;
    end if;
    if existing_mutation.request_hash is not null and (
      existing_mutation.request_hash <> request_fingerprint
      or existing_mutation.entity_type is distinct from target_entity_type
      or existing_mutation.entity_id is distinct from target_entity_id
    ) then
      select * into existing_record from public.sync_records
      where user_id = target_user_id
        and entity_type = target_entity_type
        and entity_id = target_entity_id;
      record_existed := found;
      return jsonb_build_object(
        'accepted', false,
        'replayMismatch', true,
        'serverMissing', not record_existed,
        'serverVersion', coalesce(existing_mutation.server_version, existing_record.server_version, 0),
        'record', case when record_existed then to_jsonb(existing_record) else null end
      );
    end if;
    if existing_mutation.result is not null then return existing_mutation.result; end if;
    select * into existing_record from public.sync_records
    where user_id = target_user_id and entity_type = target_entity_type and entity_id = target_entity_id;
    response_payload := jsonb_build_object(
      'accepted', existing_mutation.accepted,
      'serverVersion', existing_mutation.server_version,
      'record', to_jsonb(existing_record)
    );
    update public.sync_mutations set
      entity_type = coalesce(entity_type, target_entity_type),
      entity_id = coalesce(entity_id, target_entity_id),
      request_hash = coalesce(request_hash, request_fingerprint),
      result = response_payload
    where user_id = target_user_id and mutation_id = target_mutation_id;
    return response_payload;
  end if;

  if target_resolves_conflict_id is not null then
    select * into resolution_conflict from public.sync_conflicts
    where id = target_resolves_conflict_id
      and user_id = target_user_id
      and entity_type = target_entity_type
      and entity_id = target_entity_id
      and resolved_at is null
    for update;
    if not found then
      raise exception using errcode = '22023', message = 'Conflict resolution does not match an unresolved record conflict';
    end if;
  end if;

  perform pg_advisory_xact_lock(hashtextextended(target_user_id::text || ':' || target_entity_type || ':' || target_entity_id, 0));
  select * into existing_record from public.sync_records
  where user_id = target_user_id and entity_type = target_entity_type and entity_id = target_entity_id
  for update;
  record_existed := found;

  if record_existed and target_entity_type='tracking' and target_entity_id='singleton' and target_deleted_at is null then
    focus_merge_required := public.goalflow_merge_tracking_focus(existing_record.payload,target_payload) is distinct from target_payload;
  end if;

  if (record_existed and target_base_server_version is distinct from existing_record.server_version)
    or (record_existed and target_base_server_version = existing_record.server_version
      and target_version <= existing_record.version)
    or (not record_existed and target_base_server_version is not null)
    or focus_merge_required then
    if not record_existed then
      existing_record.server_version := 0;
      existing_record.payload := '{}'::jsonb;
      existing_record.deleted_at := null;
    end if;
    insert into public.sync_conflicts (
      user_id, entity_type, entity_id, mutation_id, base_server_version,
      server_version, local_payload, server_payload, local_deleted_at, server_deleted_at,
      local_version, local_updated_at, server_missing
    ) values (
      target_user_id, target_entity_type, target_entity_id, target_mutation_id,
      target_base_server_version, existing_record.server_version, target_payload, existing_record.payload,
      target_deleted_at, existing_record.deleted_at, target_version, target_updated_at, not record_existed
    ) returning id into conflict_id;
    response_payload := jsonb_build_object(
      'accepted', false,
      'conflictId', conflict_id,
      'serverMissing', not record_existed,
      'serverVersion', existing_record.server_version,
      'record', case when record_existed then to_jsonb(existing_record) else null end
    );
    insert into public.sync_mutations (
      user_id, mutation_id, device_id, server_version, accepted,
      entity_type, entity_id, request_hash, result
    ) values (
      target_user_id, target_mutation_id, target_device_id, existing_record.server_version, false,
      target_entity_type, target_entity_id, request_fingerprint, response_payload
    );
    if target_resolves_conflict_id is not null then
      update public.sync_conflicts set resolved_at = now()
      where id = target_resolves_conflict_id and user_id = target_user_id and resolved_at is null;
    end if;
    return response_payload;
  end if;

  -- A singleton snapshot has no per-record compare-and-swap information. Once
  -- record-level state exists, accepting one could let a stale client overwrite
  -- newer records. Preserve it as a conflict and require an upgraded client to
  -- reconcile individual records.
  if target_entity_type in ('tasks', 'goals', 'habits', 'truenorth') and target_entity_id = 'singleton'
    and jsonb_typeof(target_payload) = 'array'
    and exists (
      select 1 from public.sync_records
      where user_id = target_user_id and entity_type = target_entity_type and entity_id <> 'singleton'
    ) then
    select max(server_version), jsonb_agg(payload order by entity_id)
      into legacy_guard_version, legacy_guard_payload
    from public.sync_records
    where user_id = target_user_id and entity_type = target_entity_type and entity_id <> 'singleton';
    insert into public.sync_conflicts (
      user_id, entity_type, entity_id, mutation_id, base_server_version,
      server_version, local_payload, server_payload, local_deleted_at, server_deleted_at,
      local_version, local_updated_at, server_missing
    ) values (
      target_user_id, target_entity_type, target_entity_id, target_mutation_id,
      target_base_server_version, legacy_guard_version, target_payload, coalesce(legacy_guard_payload, '[]'::jsonb),
      target_deleted_at, null, target_version, target_updated_at, false
    ) returning id into conflict_id;
    response_payload := jsonb_build_object(
      'accepted', false,
      'conflictId', conflict_id,
      'legacySnapshotRejected', true,
      'serverMissing', false,
      'serverVersion', legacy_guard_version,
      'record', jsonb_build_object(
        'payload', coalesce(legacy_guard_payload, '[]'::jsonb),
        'deletedAt', null
      )
    );
    insert into public.sync_mutations (
      user_id, mutation_id, device_id, server_version, accepted,
      entity_type, entity_id, request_hash, result
    ) values (
      target_user_id, target_mutation_id, target_device_id, legacy_guard_version, false,
      target_entity_type, target_entity_id, request_fingerprint, response_payload
    );
    if target_resolves_conflict_id is not null then
      update public.sync_conflicts set resolved_at = now()
      where id = target_resolves_conflict_id and user_id = target_user_id and resolved_at is null;
    end if;
    return response_payload;
  end if;

  next_server_version := public.goalflow_next_change_version();
  insert into public.sync_records (
    user_id, entity_type, entity_id, version, server_version, device_id, payload, updated_at, deleted_at
  ) values (
    target_user_id, target_entity_type, target_entity_id, target_version, next_server_version,
    target_device_id, target_payload, target_updated_at, target_deleted_at
  )
  on conflict (user_id, entity_type, entity_id) do update set
    version = excluded.version,
    server_version = excluded.server_version,
    device_id = excluded.device_id,
    payload = excluded.payload,
    updated_at = excluded.updated_at,
    deleted_at = excluded.deleted_at;

  if target_entity_type = 'tasks' then
    perform public.project_goalflow_task_sync(
      target_user_id, target_entity_id, target_payload, next_server_version,
      target_updated_at, target_deleted_at
    );
  elsif target_entity_type = 'daily_plans' then
    perform public.project_goalflow_daily_plan_sync(
      target_user_id, target_entity_id, target_payload, next_server_version,
      target_updated_at, target_deleted_at
    );
  end if;
  select * into existing_record from public.sync_records
  where user_id = target_user_id and entity_type = target_entity_type and entity_id = target_entity_id;
  response_payload := jsonb_build_object(
    'accepted', true,
    'serverVersion', next_server_version,
    'record', to_jsonb(existing_record)
  );
  insert into public.sync_mutations (
    user_id, mutation_id, device_id, server_version, accepted,
    entity_type, entity_id, request_hash, result
  ) values (
    target_user_id, target_mutation_id, target_device_id, next_server_version, true,
    target_entity_type, target_entity_id, request_fingerprint, response_payload
  );
  if target_resolves_conflict_id is not null then
    update public.sync_conflicts set resolved_at = now()
    where id = target_resolves_conflict_id and user_id = target_user_id and resolved_at is null;
    if not found then
      raise exception using errcode = '22023', message = 'Conflict resolution was not durably recorded';
    end if;
  end if;
  -- Conflicts remain visible until an explicit, exact conflict resolution is
  -- durably recorded by the API. An unrelated accepted edit must not choose a side.
  return response_payload;
end;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_goalflow_sync_change(target_user_id uuid, target_candidate jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  request_fingerprint text;
  operation_id uuid;
  existing_operation public.sync_mutations%rowtype;
  current_record public.sync_records%rowtype;
  original_conflict public.sync_conflicts%rowtype;
  latest jsonb;
  record_existed boolean;
  candidate_type text := target_candidate->>'entityType';
  candidate_id text := target_candidate->>'entityId';
  candidate_conflict text := target_candidate->>'conflictId';
  change_time timestamptz;
  next_version integer;
  push_result jsonb;
  winner text := 'cloud';
  audit_result jsonb;
  merged_payload jsonb;
  focus_projection jsonb;
  history_item jsonb;
  projection_time timestamptz;
begin
  if target_user_id is null or candidate_type is null or candidate_id is null
    or candidate_conflict is null or target_candidate->'localHistory' is null or candidate_type not in (
    'tasks','goals','habits','stats','progress','hashtags','accountability',
    'truenorth','amalgam','tracking','circadian','settings','daily_plans','task_events'
  ) or length(candidate_id) not between 1 and 240
    or length(candidate_conflict) not between 1 and 600
    or jsonb_typeof(target_candidate->'localHistory') <> 'array' then
    raise exception using errcode = '22023', message = 'Invalid automatic reconciliation candidate';
  end if;
  request_fingerprint := encode(digest(convert_to(
    'goalflow-auto-reconcile-v1:' || target_candidate::text, 'utf8'), 'sha256'), 'hex');
  -- A distinct deterministic operation identity makes network retries safe
  -- without reusing or rewriting any original client mutation identity.
  operation_id := (substr(request_fingerprint,1,8) || '-' || substr(request_fingerprint,9,4)
    || '-4' || substr(request_fingerprint,14,3) || '-8' || substr(request_fingerprint,18,3)
    || '-' || substr(request_fingerprint,21,12))::uuid;
  perform pg_advisory_xact_lock(hashtextextended(target_user_id::text || ':' || operation_id::text, 0));
  perform pg_advisory_xact_lock(hashtextextended(target_user_id::text || ':' || candidate_type || ':' || candidate_id, 0));
  select * into existing_operation from public.sync_mutations
    where user_id=target_user_id and mutation_id=operation_id;
  if found and (existing_operation.request_hash is distinct from request_fingerprint
    or existing_operation.result->>'operation' is distinct from 'automatic-reconciliation') then
    raise exception using errcode = '22023', message = 'Reconciliation operation identity mismatch';
  end if;

  if existing_operation.mutation_id is null then
    if candidate_conflict ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
      select * into original_conflict from public.sync_conflicts
        where id=candidate_conflict::uuid and user_id=target_user_id for update;
      if not found or original_conflict.entity_type <> candidate_type
        or original_conflict.entity_id <> candidate_id
        or original_conflict.mutation_id::text is distinct from target_candidate->>'sourceMutationId' then
        raise exception using errcode = '22023', message = 'Reconciliation does not match the original conflict';
      end if;
    end if;
  end if;
  select * into current_record from public.sync_records
    where user_id=target_user_id and entity_type=candidate_type and entity_id=candidate_id for update;
  record_existed := found;

  if existing_operation.mutation_id is null then
    select item into latest from jsonb_array_elements(target_candidate->'localHistory') item
      order by (item->>'version')::bigint desc, item->>'mutationId' desc limit 1;
    if latest is not null then
      change_time := (latest->>'updatedAt')::timestamptz;
      if change_time is null or not isfinite(change_time) then
        raise exception using errcode = '22023', message = 'Reconciliation requires the original edit time';
      end if;
      -- Daily counters and focus controls have independent edit times. Fold
      -- focus from the whole preserved history: a later legacy daily edit may
      -- omit the preceding focus action without erasing it from that history.
      if candidate_type='tracking' and candidate_id='singleton'
        and (not record_existed or current_record.deleted_at is null) and (latest->>'deletedAt')::timestamptz is null
        and jsonb_typeof(latest->'payload')='object' then
        focus_projection := coalesce(current_record.payload,'{}'::jsonb);
        for history_item in select item from jsonb_array_elements(target_candidate->'localHistory') item
          order by (item->>'version')::bigint desc, item->>'mutationId' desc loop
          if (history_item->>'deletedAt')::timestamptz is null and jsonb_typeof(history_item->'payload')='object' then
            focus_projection := public.goalflow_merge_tracking_focus(focus_projection,history_item->'payload');
          end if;
        end loop;
        if not record_existed or (change_time > current_record.updated_at and change_time <= now()+interval '5 minutes') then
          merged_payload := latest->'payload';
          projection_time := change_time;
        else
          merged_payload := current_record.payload;
          projection_time := current_record.updated_at;
        end if;
        if focus_projection->'focusSession' is not null and focus_projection->'focusSession'<>'null'::jsonb then
          merged_payload := jsonb_set(merged_payload,'{focusSession}',focus_projection->'focusSession',true);
          projection_time := greatest(projection_time,public.goalflow_focus_session_time(focus_projection->'focusSession'));
        end if;
        if not record_existed or merged_payload is distinct from current_record.payload then
          next_version := greatest(coalesce(current_record.version,0)+1,(latest->>'version')::integer);
          push_result := public.push_sync_mutation_v2(target_user_id,gen_random_uuid(),
            'server-auto-reconcile',candidate_type,candidate_id,current_record.server_version,
            next_version,merged_payload,projection_time,null,null);
          if (push_result->>'accepted')::boolean is distinct from true then
            raise exception using errcode='40001', message='Automatic focus reconciliation must retry';
          end if;
          winner := 'field-merge';
        end if;
      else
      -- A device with a clock far in the future cannot silently displace a
      -- current cloud copy. The complete candidate remains in the audit receipt.
      if (not record_existed or (change_time > current_record.updated_at
        and change_time <= now() + interval '5 minutes'
        and candidate_type <> 'task_events'))
        and (not record_existed or latest->'payload' is distinct from current_record.payload
          or (latest->>'deletedAt')::timestamptz is distinct from current_record.deleted_at) then
        next_version := greatest(coalesce(current_record.version,0)+1, (latest->>'version')::integer);
        push_result := public.push_sync_mutation_v2(
          target_user_id, gen_random_uuid(), 'server-auto-reconcile', candidate_type, candidate_id,
          case when record_existed then current_record.server_version else null end,
          next_version, latest->'payload', change_time, (latest->>'deletedAt')::timestamptz, null
        );
        if (push_result->>'accepted')::boolean is distinct from true then
          raise exception using errcode = '40001', message = 'Automatic reconciliation must retry';
        end if;
        winner := 'local';
      end if;
      end if;
    end if;
    audit_result := jsonb_build_object(
      'operation','automatic-reconciliation','candidate',target_candidate,
      'previousCloud',case when record_existed then to_jsonb(current_record) else null end,
      'winner',winner
    );
    select * into current_record from public.sync_records
      where user_id=target_user_id and entity_type=candidate_type and entity_id=candidate_id;
    record_existed := found;
    insert into public.sync_mutations(user_id,mutation_id,device_id,server_version,accepted,
      entity_type,entity_id,request_hash,result)
    values(target_user_id,operation_id,'server-auto-reconcile',coalesce(current_record.server_version,0),true,
      candidate_type,candidate_id,request_fingerprint,audit_result);
    if original_conflict.id is not null then
      update public.sync_conflicts set resolved_at=coalesce(resolved_at,now())
        where id=original_conflict.id and user_id=target_user_id;
    end if;
  end if;
  -- On retry return the current canonical record, never an obsolete snapshot
  -- from the audit receipt. Clients still verify identity and revision before
  -- applying it, and preserve edits made while this request was in flight.
  return jsonb_build_object('reconciled',true,'receiptId',operation_id,
    'candidate',target_candidate,'serverMissing',not record_existed,
    'record',case when record_existed then to_jsonb(current_record) else null end);
end;
$function$
